/*!50001 DROP VIEW IF EXISTS `v_active_vessels`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_unicode_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_active_vessels` AS select `v`.`name` AS `vessel_name`,`acv`.`id` AS `visit_id`,`acv`.`phase` AS `phase`,`avd`.`eta` AS `eta`,`avd`.`ata` AS `ata`,`avd`.`etd` AS `etd`,`rcs`.`name` AS `service_name` from ((((`argo_carrier_visit` `acv` left join `argo_visit_details` `avd` on((`avd`.`gkey` = `acv`.`cvcvd_gkey`))) left join `vsl_vessel_visit_details` `vvd` on((`vvd`.`vvd_gkey` = `avd`.`gkey`))) left join `vsl_vessels` `v` on((`v`.`gkey` = `vvd`.`vessel_gkey`))) left join `ref_carrier_service` `rcs` on((`rcs`.`gkey` = `avd`.`service`))) where ((`acv`.`carrier_mode` = 'VESSEL') and (`acv`.`phase` in ('30ARRIVED','40WORKING','50COMPLETE'))) */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;
/*!50001 DROP VIEW IF EXISTS `v_che_productivity`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_unicode_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_che_productivity` AS select `che`.`full_name` AS `full_name`,`che`.`kind_enum` AS `kind_enum`,cast(`ime`.`t_put` as date) AS `work_date`,count(0) AS `total_moves`,count(distinct hour(`ime`.`t_put`)) AS `working_hours` from (`inv_move_event` `ime` join `xps_che` `che` on((`che`.`gkey` = coalesce(`ime`.`che_put`,`ime`.`che_fetch`)))) where (`ime`.`t_put` >= (curdate() - interval 7 day)) group by `che`.`full_name`,`che`.`kind_enum`,cast(`ime`.`t_put` as date) */;
/*!50001 SET character_set_client      = @saved_cs_client */;
/*!50001 SET character_set_results     = @saved_cs_results */;
/*!50001 SET collation_connection      = @saved_col_connection */;
/*!50001 DROP VIEW IF EXISTS `v_yard_occupancy`*/;
/*!50001 SET @saved_cs_client          = @@character_set_client */;
/*!50001 SET @saved_cs_results         = @@character_set_results */;
/*!50001 SET @saved_col_connection     = @@collation_connection */;
/*!50001 SET character_set_client      = utf8mb4 */;
/*!50001 SET character_set_results     = utf8mb4 */;
/*!50001 SET collation_connection      = utf8mb4_unicode_ci */;
/*!50001 CREATE ALGORITHM=UNDEFINED */
/*!50013 DEFINER=`root`@`localhost` SQL SECURITY DEFINER */
/*!50001 VIEW `v_yard_occupancy` AS select `iu`.`category` AS `category`,(case when (`iu`.`requires_power` = 1) then 'REEFER' else 'DRY' end) AS `container_type`,count(0) AS `units`,sum((case when (`ret`.`basic_length` = 'BASIC20') then 1.0 when (`ret`.`basic_length` = 'BASIC40') then 2.0 when (`ret`.`basic_length` = 'BASIC45') then 2.25 else 1.0 end)) AS `teus` from (((`inv_unit` `iu` join `inv_unit_fcy_visit` `iufv` on((`iufv`.`unit_gkey` = `iu`.`gkey`))) join `ref_equipment` `req` on((`req`.`gkey` = `iu`.`eq_gkey`))) join `ref_equip_type` `ret` on((`ret`.`gkey` = `req`.`eqtyp_gkey`))) where (`iufv`.`transit_state` = 'S40_YARD') group by `iu`.`category`,`container_type` */;
